<template>
  <section class="nt" aria-label="Standalone compliance tester">
    <div class="nt-intro"><h2>Try Narriva Compliance</h2><p>Paste a de-identified note and choose the facts for your test. You’ll see the same five checks, quality score and findings used in Note Workspace.</p><p class="nt-notice">Test only. Nothing is attached to a person or saved as a note, chart review or agency report. A test pass cannot approve a note or enable Quick Sign.</p></div>
    <p v-if="optionsError" role="alert" class="nt-error">{{ optionsError }} <button type="button" @click="loadOptions">Try again</button></p>
    <form @submit.prevent="run">
      <div class="nt-examples"><span>Start with your own note, or load a fictional example:</span><button type="button" :disabled="busy" @click="example(true)">Complete example</button><button type="button" :disabled="busy" @click="example(false)">Incomplete example</button></div>
      <div class="nt-grid">
        <section class="nt-panel"><h3>Note content</h3><p class="nt-warning">Do not include names, dates of birth, addresses, or other identifying information.</p><label for="nt-note">Note to check</label><textarea id="nt-note" ref="noteField" v-model="noteText" :disabled="busy" rows="17" maxlength="150000" required placeholder="Paste the complete note you want to evaluate…" /><small>{{ noteText.length.toLocaleString() }} / 150,000 characters · Not saved · processed through approved private Narriva services.</small><details><summary>Session Narrative / source facts (optional)</summary><label for="nt-source">Facts that informed the note</label><textarea id="nt-source" v-model="sessionNarrative" :disabled="busy" maxlength="150000" rows="5" /><p>Quality points require evidence in the note itself. Source facts do not fill gaps in the note automatically.</p></details></section>
        <section class="nt-panel"><h3>Test facts</h3><p>These choices simulate encounter context. Missing facts remain missing; they are not confirmed against a chart.</p><div class="nt-fields">
          <label>Service<select v-model="context.serviceCode" :disabled="busy || optionsLoading" required><option value="">{{ optionsLoading ? 'Loading services…' : 'Choose a service' }}</option><option v-for="s in services" :key="s.code" :value="s.code">{{ s.code }} — {{ s.label }}{{ s.referenceAvailable ? '' : ' · reference unavailable' }}</option></select></label>
          <label v-if="proBono">Clinical service provided<select v-model="context.underlyingServiceCode" :disabled="busy"><option value="">Choose the underlying service</option><option v-for="s in clinicalServices" :key="s.code" :value="s.code">{{ s.code }} — {{ s.label }}</option></select></label>
          <label>Test provider qualification<select v-model="context.credentialTier" :disabled="busy" required><option value="">Choose qualification</option><option value="qbha">QBHA</option><option value="bachelors">Bachelor’s level</option><option value="intern_plus">Clinical intern / licensed clinical role</option></select></label>
          <label>Service date<input v-model="context.dateOfService" :disabled="busy" type="date" /></label>
          <label>Duration (minutes)<input v-model.number="context.durationMinutes" :disabled="busy" type="number" min="1" max="1440" /></label><small>This test checks duration only. Start/end times are not evaluated.</small>
          <ClinicalLocationPicker v-model="testLocation" :choices="locations" :disabled="busy" :unavailable="locationsUnavailable" />
          <label>Participants<select v-model="context.participants" :disabled="busy"><option value="">Not specified</option><option v-for="value in ['Client only','Client and guardian','Guardian without client','Client and others']" :key="value">{{ value }}</option></select></label>
          <label>Participation consent<select v-model="context.consentConfirmed" :disabled="busy"><option :value="null">Not specified</option><option :value="true">Explicit consent documented in test</option><option :value="false">Not documented</option></select></label>
          <ClinicalDiagnosisSearch v-model="context.diagnosis" label="Diagnosis for the test" :agency-id="agencyId" :date-of-service="context.dateOfService" :disabled="busy" />
          <label>Diagnostic justification<textarea v-model="context.diagnosticJustification" :disabled="busy" rows="2" maxlength="8000" /></label>
          <label>Presenting problem / reason for service<textarea v-model="context.presentingProblem" :disabled="busy" rows="2" maxlength="8000" /></label>
          <label>Existing goal or objective (optional)<textarea v-model="context.goals" :disabled="busy" rows="2" maxlength="8000" /></label>
          <details><summary>Risk and assessment evidence (optional)</summary><p>Leave unassessed fields blank. A required assessment cannot be waived by leaving these choices blank.</p><label v-for="item in riskFields" :key="item.key">{{ item.label }}<select v-model="context.riskDomains[item.key]" :disabled="busy"><option value="">Not assessed / not supplied</option><option value="denied">Denied in test assessment</option><option value="present">Present</option><option value="uncertain">Uncertain</option><option value="historical">Historical</option></select></label><label class="nt-check"><input v-model="context.riskAssessmentCompleted" :disabled="busy" type="checkbox" />Test includes a completed, reviewed risk assessment</label><label>Referenced assessment evidence for this test<textarea v-model="context.assessmentExcerpt" :disabled="busy" maxlength="8000" rows="3" placeholder="De-identified findings or a fictional assessment excerpt" /></label><p>This text is simulated evidence; no clinical document is attached or verified.</p></details>
        </div></section>
      </div>
      <div class="nt-actions"><button type="submit" class="nt-primary" :disabled="busy || optionsLoading || !noteText.trim() || !context.serviceCode || !context.credentialTier">{{ busy ? 'Checking note…' : 'Run test check' }}</button><button type="button" @click="clear">{{ busy ? 'Cancel and clear' : 'Clear test' }}</button><span v-if="busy" role="status">Narriva is evaluating this test. Results appear after the server responds.</span></div>
    </form>
    <p v-if="error" class="nt-error" role="alert">{{ error }}</p>
    <div v-if="busy || review" ref="resultField"><p class="nt-result-label">TEST RESULT · {{ review?.rulesVersion || rulesVersion }}</p><NarrivaCompliancePanel :review="review" :busy="busy" read-only test-mode /><p v-if="review?.limitations" class="nt-notice">{{ review.limitations }}</p></div>
  </section>
</template>
<script setup>
import {computed,nextTick,onBeforeUnmount,reactive,ref,watch} from 'vue';
import api from '../../services/api';
import NarrivaCompliancePanel from './NarrivaCompliancePanel.vue';
import ClinicalLocationPicker from './ClinicalLocationPicker.vue';
import ClinicalDiagnosisSearch from './ClinicalDiagnosisSearch.vue';
import {NARRIVA_CHECKS} from '../../config/narrivaBrand.js';
const props=defineProps({agencyId:{type:Number,required:true}});
const fresh=()=>({serviceCode:'',underlyingServiceCode:'',credentialTier:'',dateOfService:'',durationMinutes:null,modality:'',placeOfService:'',location:'',locationSelection:'',participants:'',consentConfirmed:null,diagnosis:'',diagnosticJustification:'',presentingProblem:'',goals:'',assessmentExcerpt:'',riskAssessmentCompleted:false,riskDomains:{suicidalIdeation:'',homicidalIdeation:'',selfHarm:''}});
const context=reactive(fresh()),noteText=ref(''),sessionNarrative=ref(''),review=ref(null),busy=ref(false),error=ref(''),services=ref([]),optionsLoading=ref(false),optionsError=ref(''),rulesVersion=ref(''),noteField=ref(null),resultField=ref(null);
const riskFields=[{key:'suicidalIdeation',label:'Suicidal ideation'},{key:'homicidalIdeation',label:'Homicidal ideation'},{key:'selfHarm',label:'Self-harm'}];
const locations=ref([]),locationsUnavailable=ref(false);
const testLocation=computed({get:()=>({locationSelection:context.locationSelection,locationLabel:context.location,placeOfService:context.placeOfService,modality:context.modality}),set:value=>{
 context.locationSelection=value.locationSelection;context.placeOfService=value.placeOfService;context.modality=value.modality;
 context.location=['video','phone'].includes(value.modality)?'Telehealth':({'11':'Office','03':'School','12':'Home'})[value.placeOfService] || '';
}});
const proBono=computed(()=>/PRO.?BONO/i.test(context.serviceCode));
const clinicalServices=computed(()=>services.value.filter(s=>!/PRO.?BONO/i.test(s.code)));
let generation=0,optionsGeneration=0,controller;
function clear(){generation++;controller?.abort();controller=null;busy.value=false;review.value=null;error.value='';noteText.value='';sessionNarrative.value='';Object.assign(context,fresh());}
watch(()=>JSON.stringify([noteText.value,sessionNarrative.value,context]),()=>{review.value=null;error.value='';},{flush:'sync'});
async function loadOptions(){const sequence=++optionsGeneration,id=props.agencyId;optionsLoading.value=true;optionsError.value='';services.value=[];locations.value=[];locationsUnavailable.value=false;try{const {data}=await api.get('/narriva/test-review/options',{params:{agencyId:id},skipGlobalLoading:true});if(sequence!==optionsGeneration||id!==props.agencyId)return;services.value=data.services||[];locations.value=data.locations||[];locationsUnavailable.value=data.locationsUnavailable===true;rulesVersion.value=data.rulesVersion||'';}catch(e){if(sequence===optionsGeneration)optionsError.value=e.response?.data?.error?.message||'Test services could not be loaded.';}finally{if(sequence===optionsGeneration)optionsLoading.value=false;}}
watch(()=>props.agencyId,()=>{clear();loadOptions();},{immediate:true});
async function run(){if(busy.value||!noteText.value.trim()||!context.serviceCode||!context.credentialTier)return;const sequence=++generation,id=props.agencyId;controller=new AbortController();busy.value=true;review.value=null;error.value='';try{const {data}=await api.post('/narriva/test-review',{agencyId:id,noteText:noteText.value,sessionNarrative:sessionNarrative.value,context:JSON.parse(JSON.stringify(context))},{skipGlobalLoading:true,timeout:180000,signal:controller.signal});if(sequence!==generation||id!==props.agencyId)return;if(data.review?.testOnly!==true||data.review?.quickSignEligible!==false)throw new Error('Invalid test result');review.value=data.review;await nextTick();resultField.value?.scrollIntoView?.({behavior:'smooth',block:'start'});}catch(e){if(sequence===generation){error.value=e.response?.data?.error?.message||'The test could not complete. Your text is still here; retry when the service is available.';review.value={testOnly:true,status:'unavailable',quickSignEligible:false,rulesVersion:rulesVersion.value,checks:NARRIVA_CHECKS.map(c=>({...c,status:'unavailable',findings:[]}))};}}finally{if(sequence===generation){busy.value=false;controller=null;}}}
function example(complete){clear();Object.assign(context,{serviceCode:services.value.some(s=>s.code==='90837')?'90837':services.value.some(s=>s.code==='H0004')?'H0004':services.value[0]?.code||'',credentialTier:'intern_plus',dateOfService:'2026-01-15',durationMinutes:60,modality:'in_person',placeOfService:locations.value.find(l=>l.placeOfService==='11')?'11':'12',location:locations.value.find(l=>l.placeOfService==='11')?'Office':'Home',locationSelection:locations.value.find(l=>l.placeOfService==='11')?.value || '__home__',participants:'Client only',consentConfirmed:true,diagnosis:'F41.1',diagnosticJustification:'Persistent worry and physical anxiety interfere with participation in school tasks.',presentingProblem:'Anxiety and avoidance interfere with school task participation.',goals:'Practice one coping strategy during school-related distress on three days each week.'});noteText.value=complete?'Reason for service: anxiety causes avoidance of school tasks and missed class participation. Existing objective: practice one coping strategy during school-related distress on three days each week. Clinician taught paced breathing, demonstrated the steps, and coached Client through two practice rounds to reduce physical anxiety and support task participation. Client stayed engaged, independently repeated the sequence and reported tension changing from seven out of ten before practice to four out of ten afterward. Client described using the skill once since the prior session and identified forgetting to practice as a barrier; this is partial progress toward the existing objective. Client will practice paced breathing before one classroom task on three school days and track use. Clinician will review the log at the next weekly visit and adapt the plan if the barrier persists. Participation consent was confirmed for this encounter. No separate assessment was administered or referenced.':'Discussed anxiety. Client participated. Continue treatment.';nextTick(()=>noteField.value?.focus());}
onBeforeUnmount(()=>{generation++;optionsGeneration++;controller?.abort();});
</script>
<style scoped>
.nt{color:#193951}.nt-intro{max-width:980px}.nt h2{font-size:24px;margin:8px 0}.nt h3{margin:0 0 12px;font-size:19px}.nt p{line-height:1.55}.nt-notice,.nt-warning{padding:12px 15px;border-left:3px solid #c8a54d;background:#fff9eb;border-radius:5px;font-size:13px}.nt-warning{margin-top:0}.nt-grid{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1fr);gap:20px}.nt-panel{padding:22px;background:#fff;border:1px solid #d5e0eb;border-radius:13px;min-width:0}.nt label{display:grid;gap:6px;font-size:13px;font-weight:600;margin:9px 0}.nt textarea,.nt select,.nt input:not([type=checkbox]){font:inherit;font-weight:400;color:#193951;width:100%;box-sizing:border-box;padding:11px;border:1px solid #bacddd;border-radius:7px;background:white;min-width:0}.nt textarea{resize:vertical;line-height:1.55}.nt textarea:focus,.nt input:focus,.nt select:focus{outline:2px solid #90b7e5;outline-offset:2px}.nt small{display:block;font-size:12px;color:#5f7487;margin-top:8px}.nt-row{display:flex;gap:10px}.nt-row>label{flex:1;min-width:0}.nt details{margin-top:15px;padding-top:12px;border-top:1px solid #d9e4ee;font-size:13px}.nt summary{cursor:pointer;font-weight:650;padding:4px 0}.nt button{font:inherit;border:1px solid #c6d5e3;background:white;color:#205783;padding:10px 14px;border-radius:8px;cursor:pointer}.nt button:disabled{opacity:.55;cursor:default}.nt .nt-primary{background:#194f7a;color:white;border-color:#194f7a}.nt-examples,.nt-actions{display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin:18px 0;font-size:13px}.nt-actions{font-size:14px}.nt-error{padding:12px;color:#9c2727;background:#fff0f0;border-radius:7px}.nt-check{display:flex!important;align-items:center;gap:8px!important}.nt-result-label{font-size:12px;font-weight:700;color:#705e35;letter-spacing:.07em;margin:28px 0 0}@media(min-width:1600px){.nt-grid{grid-template-columns:minmax(0,1.5fr) minmax(480px,1fr)}}@media(max-width:850px){.nt-grid{grid-template-columns:1fr}.nt-panel{padding:16px}.nt-row{flex-wrap:wrap}.nt-row>label{min-width:100px}}
</style>
